Dataspatium.assets.register("presets/api/kolada.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"kolada\",\n  \"name\": \"Kolada (kommun- och regiondatabasen)\",\n  \"publisher\": \"Rådet för främjande av kommunala analyser (RKA)\",\n  \"description\": \"Nyckeltal för kommuner och regioner: ekonomi, skola, omsorg, befolkning, miljö och mycket mer. Sök nyckeltal (id som N01951), hämta värden per år för alla kommuner eller för valda kommuner över tid.\",\n  \"docs\": \"https://api.kolada.se/v3/docs\",\n  \"license\": { \"name\": \"Öppna data, fri att använda med källangivelse Kolada/RKA\", \"url\": \"https://www.kolada.se/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://api.kolada.se/v3\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"kpi\",\n      \"name\": \"Sök nyckeltal\",\n      \"description\": \"Nyckeltal vars titel innehåller sökordet. Kolumnen id används sedan för att hämta värden.\",\n      \"method\": \"GET\",\n      \"path\": \"/kpi\",\n      \"params\": [\n        { \"name\": \"title\", \"in\": \"query\", \"label\": \"Sökord i titeln\", \"type\": \"string\", \"required\": true, \"example\": \"invånare\" },\n        { \"name\": \"operating_area\", \"in\": \"query\", \"label\": \"Verksamhetsområde (valfritt)\", \"type\": \"string\", \"example\": \"Befolkning\" },\n        { \"name\": \"per_page\", \"in\": \"query\", \"type\": \"number\", \"default\": 500, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"next-url\", \"path\": \"next_url\", \"maxPages\": 20 },\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"drop\": [\"search_score\"] },\n      \"dataset\": { \"name\": \"Kolada nyckeltal: {title}\" }\n    },\n    {\n      \"id\": \"municipalities\",\n      \"name\": \"Kommuner och regioner\",\n      \"description\": \"Lista över kommuner (typ K) och regioner (typ L) med Koladas id.\",\n      \"method\": \"GET\",\n      \"path\": \"/municipality\",\n      \"params\": [\n        { \"name\": \"type\", \"in\": \"query\", \"label\": \"Typ\", \"type\": \"enum\", \"options\": [{ \"value\": \"K\", \"label\": \"Kommuner\" }, { \"value\": \"L\", \"label\": \"Regioner\" }] },\n        { \"name\": \"per_page\", \"in\": \"query\", \"type\": \"number\", \"default\": 500, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"next-url\", \"path\": \"next_url\", \"maxPages\": 10 },\n      \"response\": { \"format\": \"json\", \"path\": \"values\" },\n      \"dataset\": { \"name\": \"Kolada kommuner och regioner\" }\n    },\n    {\n      \"id\": \"data-year\",\n      \"name\": \"Värden per år (alla kommuner och regioner)\",\n      \"description\": \"Alla kommuners och regioners värden för ett eller flera nyckeltal och år.\",\n      \"method\": \"GET\",\n      \"path\": \"/data/kpi/{kpi_id}/year/{year}\",\n      \"params\": [\n        { \"name\": \"kpi_id\", \"in\": \"path\", \"label\": \"Nyckeltal (id, flera med komma)\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"N01951\" },\n        { \"name\": \"year\", \"in\": \"path\", \"label\": \"År (flera med komma)\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"2022,2023\" },\n        { \"name\": \"per_page\", \"in\": \"query\", \"type\": \"number\", \"default\": 2000, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"next-url\", \"path\": \"next_url\", \"maxPages\": 100 },\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"explode\": \"values\", \"rename\": { \"kpi\": \"nyckeltal\", \"municipality\": \"kommun_id\", \"period\": \"ar\", \"gender\": \"kon\", \"value\": \"varde\", \"count\": \"antal\" }, \"drop\": [\"isdeleted\"] },\n      \"dataset\": { \"name\": \"Kolada {kpi_id} {year}\", \"keys\": [\"nyckeltal\", \"kommun_id\", \"ar\", \"kon\"] }\n    },\n    {\n      \"id\": \"data-municipality\",\n      \"name\": \"Värden för valda kommuner (alla år)\",\n      \"description\": \"Hela tidsserien för ett eller flera nyckeltal i valda kommuner eller regioner.\",\n      \"method\": \"GET\",\n      \"path\": \"/data/kpi/{kpi_id}/municipality/{municipality_id}\",\n      \"params\": [\n        { \"name\": \"kpi_id\", \"in\": \"path\", \"label\": \"Nyckeltal (id, flera med komma)\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"N01951\" },\n        { \"name\": \"municipality_id\", \"in\": \"path\", \"label\": \"Kommun eller region\", \"type\": \"multi\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"municipalities\", \"value\": \"id\", \"label\": \"title\" } },\n        { \"name\": \"per_page\", \"in\": \"query\", \"type\": \"number\", \"default\": 2000, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"next-url\", \"path\": \"next_url\", \"maxPages\": 100 },\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"explode\": \"values\", \"rename\": { \"kpi\": \"nyckeltal\", \"municipality\": \"kommun_id\", \"period\": \"ar\", \"gender\": \"kon\", \"value\": \"varde\", \"count\": \"antal\" }, \"drop\": [\"isdeleted\"] },\n      \"dataset\": { \"name\": \"Kolada {kpi_id} per kommun\", \"keys\": [\"nyckeltal\", \"kommun_id\", \"ar\", \"kon\"] }\n    },\n    {\n      \"id\": \"data-municipality-year\",\n      \"name\": \"Värden för valda kommuner och år\",\n      \"method\": \"GET\",\n      \"path\": \"/data/kpi/{kpi_id}/municipality/{municipality_id}/year/{year}\",\n      \"params\": [\n        { \"name\": \"kpi_id\", \"in\": \"path\", \"label\": \"Nyckeltal (id, flera med komma)\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"N01951\" },\n        { \"name\": \"municipality_id\", \"in\": \"path\", \"label\": \"Kommun eller region\", \"type\": \"multi\", \"required\": true, \"optionsFrom\": { \"endpoint\": \"municipalities\", \"value\": \"id\", \"label\": \"title\" } },\n        { \"name\": \"year\", \"in\": \"path\", \"label\": \"År (flera med komma)\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"2020,2021,2022,2023\" },\n        { \"name\": \"per_page\", \"in\": \"query\", \"type\": \"number\", \"default\": 2000, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"next-url\", \"path\": \"next_url\", \"maxPages\": 100 },\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"explode\": \"values\", \"rename\": { \"kpi\": \"nyckeltal\", \"municipality\": \"kommun_id\", \"period\": \"ar\", \"gender\": \"kon\", \"value\": \"varde\", \"count\": \"antal\" }, \"drop\": [\"isdeleted\"] },\n      \"dataset\": { \"name\": \"Kolada {kpi_id} {year}\", \"keys\": [\"nyckeltal\", \"kommun_id\", \"ar\", \"kon\"] }\n    }\n  ],\n  \"notes\": \"kon: T = totalt, M = män, K = kvinnor. kommun_id 0000 är riket; regioner har id 00xx.\",\n  \"i18n\": {\n    \"en\": {\"name\": \"Kolada (municipality and region database)\", \"publisher\": \"Council for the Promotion of Municipal Analyses (RKA)\", \"description\": \"Key figures for Swedish municipalities and regions: economy, school, care, population, environment and much more. Search key figures (ids such as N01951), fetch values per year for all municipalities or for chosen municipalities over time.\", \"notes\": \"kon (sex): T = total, M = men, K = women. kommun_id 0000 is the whole country; regions have ids 00xx.\", \"endpoints\": {\"kpi\": {\"name\": \"Search key figures\", \"description\": \"Key figures whose title contains the search word. The id column is then used to fetch values.\", \"params\": {\"title\": {\"label\": \"Search word in the title\"}, \"operating_area\": {\"label\": \"Area of operation (optional)\"}}}, \"municipalities\": {\"name\": \"Municipalities and regions\", \"description\": \"List of municipalities (type K) and regions (type L) with Kolada's ids.\", \"params\": {\"type\": {\"label\": \"Type\", \"options\": {\"K\": \"Municipalities\", \"L\": \"Regions\"}}}}, \"data-year\": {\"name\": \"Values per year (all municipalities and regions)\", \"description\": \"All municipalities' and regions' values for one or more key figures and years.\", \"params\": {\"kpi_id\": {\"label\": \"Key figure (id, several with commas)\"}, \"year\": {\"label\": \"Year (several with commas)\"}}}, \"data-municipality\": {\"name\": \"Values for chosen municipalities (all years)\", \"description\": \"The whole time series for one or more key figures in chosen municipalities or regions.\", \"params\": {\"kpi_id\": {\"label\": \"Key figure (id, several with commas)\"}, \"municipality_id\": {\"label\": \"Municipality or region\"}}}, \"data-municipality-year\": {\"name\": \"Values for chosen municipalities and years\", \"params\": {\"kpi_id\": {\"label\": \"Key figure (id, several with commas)\"}, \"municipality_id\": {\"label\": \"Municipality or region\"}, \"year\": {\"label\": \"Year (several with commas)\"}}}}, \"dataset\": {\"kpi\": \"Kolada key figures: {title}\", \"municipalities\": \"Kolada municipalities and regions\", \"data-municipality\": \"Kolada {kpi_id} per municipality\"}},\n    \"da\": {\"name\": \"Kolada (svensk kommune- og regiondatabase)\", \"publisher\": \"Rådet för främjande av kommunala analyser (RKA)\", \"description\": \"Nøgletal for svenske kommuner og regioner: økonomi, skole, omsorg, befolkning, miljø og meget mere. Søg nøgletal (id som N01951), hent værdier pr. år for alle kommuner eller for valgte kommuner over tid.\", \"notes\": \"kon (køn): T = i alt, M = mænd, K = kvinder. kommun_id 0000 er hele landet; regioner har id 00xx.\", \"endpoints\": {\"kpi\": {\"name\": \"Søg nøgletal\", \"description\": \"Nøgletal, hvis titel indeholder søgeordet. Kolonnen id bruges derefter til at hente værdier.\", \"params\": {\"title\": {\"label\": \"Søgeord i titlen\"}, \"operating_area\": {\"label\": \"Virksomhedsområde (valgfrit)\"}}}, \"municipalities\": {\"name\": \"Kommuner og regioner\", \"description\": \"Liste over kommuner (type K) og regioner (type L) med Koladas id.\", \"params\": {\"type\": {\"label\": \"Type\", \"options\": {\"K\": \"Kommuner\", \"L\": \"Regioner\"}}}}, \"data-year\": {\"name\": \"Værdier pr. år (alle kommuner og regioner)\", \"description\": \"Alle kommuners og regioners værdier for et eller flere nøgletal og år.\", \"params\": {\"kpi_id\": {\"label\": \"Nøgletal (id, flere med komma)\"}, \"year\": {\"label\": \"År (flere med komma)\"}}}, \"data-municipality\": {\"name\": \"Værdier for valgte kommuner (alle år)\", \"description\": \"Hele tidsserien for et eller flere nøgletal i valgte kommuner eller regioner.\", \"params\": {\"kpi_id\": {\"label\": \"Nøgletal (id, flere med komma)\"}, \"municipality_id\": {\"label\": \"Kommune eller region\"}}}, \"data-municipality-year\": {\"name\": \"Værdier for valgte kommuner og år\", \"params\": {\"kpi_id\": {\"label\": \"Nøgletal (id, flere med komma)\"}, \"municipality_id\": {\"label\": \"Kommune eller region\"}, \"year\": {\"label\": \"År (flere med komma)\"}}}}, \"dataset\": {\"kpi\": \"Kolada nøgletal: {title}\", \"municipalities\": \"Kolada kommuner og regioner\", \"data-municipality\": \"Kolada {kpi_id} pr. kommune\"}},\n    \"nb\": {\"name\": \"Kolada (svensk kommune- og regiondatabase)\", \"publisher\": \"Rådet för främjande av kommunala analyser (RKA)\", \"description\": \"Nøkkeltall for svenske kommuner og regioner: økonomi, skole, omsorg, befolkning, miljø og mye mer. Søk nøkkeltall (id som N01951), hent verdier per år for alle kommuner eller for valgte kommuner over tid.\", \"notes\": \"kon (kjønn): T = totalt, M = menn, K = kvinner. kommun_id 0000 er hele landet; regioner har id 00xx.\", \"endpoints\": {\"kpi\": {\"name\": \"Søk nøkkeltall\", \"description\": \"Nøkkeltall der tittelen inneholder søkeordet. Kolonnen id brukes deretter for å hente verdier.\", \"params\": {\"title\": {\"label\": \"Søkeord i tittelen\"}, \"operating_area\": {\"label\": \"Virksomhetsområde (valgfritt)\"}}}, \"municipalities\": {\"name\": \"Kommuner og regioner\", \"description\": \"Liste over kommuner (type K) og regioner (type L) med Koladas id.\", \"params\": {\"type\": {\"label\": \"Type\", \"options\": {\"K\": \"Kommuner\", \"L\": \"Regioner\"}}}}, \"data-year\": {\"name\": \"Verdier per år (alle kommuner og regioner)\", \"description\": \"Alle kommuners og regioners verdier for ett eller flere nøkkeltall og år.\", \"params\": {\"kpi_id\": {\"label\": \"Nøkkeltall (id, flere med komma)\"}, \"year\": {\"label\": \"År (flere med komma)\"}}}, \"data-municipality\": {\"name\": \"Verdier for valgte kommuner (alle år)\", \"description\": \"Hele tidsserien for ett eller flere nøkkeltall i valgte kommuner eller regioner.\", \"params\": {\"kpi_id\": {\"label\": \"Nøkkeltall (id, flere med komma)\"}, \"municipality_id\": {\"label\": \"Kommune eller region\"}}}, \"data-municipality-year\": {\"name\": \"Verdier for valgte kommuner og år\", \"params\": {\"kpi_id\": {\"label\": \"Nøkkeltall (id, flere med komma)\"}, \"municipality_id\": {\"label\": \"Kommune eller region\"}, \"year\": {\"label\": \"År (flere med komma)\"}}}}, \"dataset\": {\"kpi\": \"Kolada nøkkeltall: {title}\", \"municipalities\": \"Kolada kommuner og regioner\", \"data-municipality\": \"Kolada {kpi_id} per kommune\"}},\n    \"fi\": {\"name\": \"Kolada (Ruotsin kunta- ja aluetietokanta)\", \"publisher\": \"Rådet för främjande av kommunala analyser (RKA)\", \"description\": \"Ruotsin kuntien ja alueiden tunnusluvut: talous, koulu, hoiva, väestö, ympäristö ja paljon muuta. Hae tunnuslukuja (id kuten N01951), nouda arvot vuosittain kaikille kunnille tai valituille kunnille ajan mittaan.\", \"notes\": \"kon (sukupuoli): T = yhteensä, M = miehet, K = naiset. kommun_id 0000 on koko maa; alueiden id on 00xx.\", \"endpoints\": {\"kpi\": {\"name\": \"Hae tunnuslukuja\", \"description\": \"Tunnusluvut, joiden nimessä on hakusana. Saraketta id käytetään sitten arvojen noutamiseen.\", \"params\": {\"title\": {\"label\": \"Hakusana nimessä\"}, \"operating_area\": {\"label\": \"Toimiala (valinnainen)\"}}}, \"municipalities\": {\"name\": \"Kunnat ja alueet\", \"description\": \"Luettelo kunnista (tyyppi K) ja alueista (tyyppi L) Koladan id:llä.\", \"params\": {\"type\": {\"label\": \"Tyyppi\", \"options\": {\"K\": \"Kunnat\", \"L\": \"Alueet\"}}}}, \"data-year\": {\"name\": \"Arvot vuosittain (kaikki kunnat ja alueet)\", \"description\": \"Kaikkien kuntien ja alueiden arvot yhdelle tai useammalle tunnusluvulle ja vuodelle.\", \"params\": {\"kpi_id\": {\"label\": \"Tunnusluku (id, useita pilkulla)\"}, \"year\": {\"label\": \"Vuosi (useita pilkulla)\"}}}, \"data-municipality\": {\"name\": \"Arvot valituille kunnille (kaikki vuodet)\", \"description\": \"Koko aikasarja yhdelle tai useammalle tunnusluvulle valituissa kunnissa tai alueilla.\", \"params\": {\"kpi_id\": {\"label\": \"Tunnusluku (id, useita pilkulla)\"}, \"municipality_id\": {\"label\": \"Kunta tai alue\"}}}, \"data-municipality-year\": {\"name\": \"Arvot valituille kunnille ja vuosille\", \"params\": {\"kpi_id\": {\"label\": \"Tunnusluku (id, useita pilkulla)\"}, \"municipality_id\": {\"label\": \"Kunta tai alue\"}, \"year\": {\"label\": \"Vuosi (useita pilkulla)\"}}}}, \"dataset\": {\"kpi\": \"Kolada tunnusluvut: {title}\", \"municipalities\": \"Kolada kunnat ja alueet\", \"data-municipality\": \"Kolada {kpi_id} kunnittain\"}},\n    \"is\": {\"name\": \"Kolada (gagnagrunnur sænskra sveitarfélaga og landshluta)\", \"publisher\": \"Rådet för främjande av kommunala analyser (RKA)\", \"description\": \"Lykiltölur fyrir sænsk sveitarfélög og landshluta: fjármál, skóli, umönnun, mannfjöldi, umhverfi og margt fleira. Leitaðu að lykiltölum (auðkenni eins og N01951), sæktu gildi eftir árum fyrir öll sveitarfélög eða fyrir valin sveitarfélög yfir tíma.\", \"notes\": \"kon (kyn): T = alls, M = karlar, K = konur. kommun_id 0000 er landið allt; landshlutar hafa auðkenni 00xx.\", \"endpoints\": {\"kpi\": {\"name\": \"Leita að lykiltölum\", \"description\": \"Lykiltölur þar sem heitið inniheldur leitarorðið. Dálkurinn id er síðan notaður til að sækja gildi.\", \"params\": {\"title\": {\"label\": \"Leitarorð í heiti\"}, \"operating_area\": {\"label\": \"Starfssvið (valfrjálst)\"}}}, \"municipalities\": {\"name\": \"Sveitarfélög og landshlutar\", \"description\": \"Listi yfir sveitarfélög (gerð K) og landshluta (gerð L) með auðkennum Kolada.\", \"params\": {\"type\": {\"label\": \"Gerð\", \"options\": {\"K\": \"Sveitarfélög\", \"L\": \"Landshlutar\"}}}}, \"data-year\": {\"name\": \"Gildi eftir árum (öll sveitarfélög og landshlutar)\", \"description\": \"Gildi allra sveitarfélaga og landshluta fyrir eina eða fleiri lykiltölur og ár.\", \"params\": {\"kpi_id\": {\"label\": \"Lykiltala (auðkenni, fleiri með kommum)\"}, \"year\": {\"label\": \"Ár (fleiri með kommum)\"}}}, \"data-municipality\": {\"name\": \"Gildi fyrir valin sveitarfélög (öll ár)\", \"description\": \"Öll tímaröðin fyrir eina eða fleiri lykiltölur í völdum sveitarfélögum eða landshlutum.\", \"params\": {\"kpi_id\": {\"label\": \"Lykiltala (auðkenni, fleiri með kommum)\"}, \"municipality_id\": {\"label\": \"Sveitarfélag eða landshluti\"}}}, \"data-municipality-year\": {\"name\": \"Gildi fyrir valin sveitarfélög og ár\", \"params\": {\"kpi_id\": {\"label\": \"Lykiltala (auðkenni, fleiri með kommum)\"}, \"municipality_id\": {\"label\": \"Sveitarfélag eða landshluti\"}, \"year\": {\"label\": \"Ár (fleiri með kommum)\"}}}}, \"dataset\": {\"kpi\": \"Kolada lykiltölur: {title}\", \"municipalities\": \"Kolada sveitarfélög og landshlutar\", \"data-municipality\": \"Kolada {kpi_id} eftir sveitarfélögum\"}}\n  }\n}\n");
